function rustRoutes(
  contexts: readonly { name: string; commands: readonly { name: string }[]; queries: readonly { name: string }[]; entities?: readonly { name: string; description: string }[]; valueObjects?: readonly { name: string; description: string }[] }[],
): { content: string; routeCount: number } {
  const lines: string[] = [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    extract::Query,',
    '    http::StatusCode,',
    '    response::Json,',
    '    routing::{get, post},',
    '    Router,',
    '};',
    'use serde_json::{json, Value};',
    'use std::collections::HashMap;',
    'use tokio;',
    '',
    'pub fn create_router() -> Router {',
    '    Router::new()',
    '        .route("/health/healthz", get(crate::health::healthz))',
    '        .route("/health/readyz", get(crate::health::readyz))',
  ];

  let routeCount = 0;

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));

    for (const cmd of ctx.commands) {
      const cmdSlug = slugify(cmd.name);
      const fnName = snakeCase(cmd.name);
      lines.push(`        .route("/api/${ctxSlug}/${cmdSlug}", post(handle_${fnName}))`);
      routeCount++;
    }

    for (const query of ctx.queries) {
      const querySlug = slugify(query.name);
      const fnName = snakeCase(query.name);
      lines.push(`        .route("/api/${ctxSlug}/${querySlug}", get(handle_${fnName}))`);
      routeCount++;
    }
  }

  lines.push('}');
  lines.push('');

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));
    lines.push(`// Bounded context: ${ctx.name}`);

    for (const cmd of ctx.commands) {
      const fnName = snakeCase(cmd.name);
      const cmdSlug = slugify(cmd.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Json(body): Json<Value>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(`    let start = std::time::Instant::now();`);
      lines.push(buildRustMockCommandJson(ctxSlug, cmdSlug));
      lines.push(`}`);
      lines.push('');
    }

    for (const query of ctx.queries) {
      const fnName = snakeCase(query.name);
      const querySlug = slugify(query.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Query(params): Query<HashMap<String, String>>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(buildRustMockQueryJson(ctxSlug, querySlug));
      lines.push(`}`);
      lines.push('');
    }
  }

  return { content: lines.join('\n'), routeCount };
}

function rustMiddleware(): string {
  return [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    body::Body,',
    '    http::{Request, Response},',
    '    middleware::Next,',
    '    response::IntoResponse,',
    '};',
    'use uuid::Uuid;',
    '',
    'pub async fn correlation_middleware(',
    '    mut req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let correlation_id = req',
    '        .headers()',
    '        .get("x-correlation-id")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string())',
    '        .unwrap_or_else(|| Uuid::new_v4().to_string());',
    '',
    '    req.extensions_mut().insert(correlation_id.clone());',
    '',
    '    let mut response = next.run(req).await;',
    '    response.headers_mut().insert(',
    '        "x-correlation-id",',
    '        correlation_id.parse().unwrap(),',
    '    );',
    '    response',
    '}',
    '',
    'fn jwks_uri() -> String {',
    '    std::env::var("IAM_JWKS_URI")',
    '        .unwrap_or_else(|_| "https://www.googleapis.com/oauth2/v3/certs".into())',
    '}',
    '',
    'fn iam_audience() -> Option<String> {',
    '    std::env::var("IAM_AUDIENCE").ok().filter(|s| !s.is_empty())',
    '}',
    '',
    'fn iam_issuers() -> Vec<String> {',
    '    std::env::var("IAM_ISSUERS")',
    '        .unwrap_or_else(|_| "https://accounts.google.com".into())',
    '        .split(\',\')',
    '        .map(|s| s.trim().to_string())',
    '        .filter(|s| !s.is_empty())',
    '        .collect()',
    '}',
    '',
    'pub async fn iam_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let path = req.uri().path().to_string();',
    '    if path == "/health/healthz" || path == "/health/readyz" {',
    '        return next.run(req).await.into_response();',
    '    }',
    '',
    '    let auth_header = req',
    '        .headers()',
    '        .get("authorization")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string());',
    '',
    '    match auth_header {',
    '        Some(header) if header.starts_with("Bearer ") => {',
    '            let token = &header[7..];',
    '            let header = match jsonwebtoken::decode_header(token) {',
    '                Ok(h) => h,',
    '                Err(_) => return unauthorized("Malformed token header"),',
    '            };',
    '            let kid = match header.kid {',
    '                Some(k) => k,',
    '                None => return unauthorized("Token missing kid claim"),',
    '            };',
    '',
    '            let jwks_url = jwks_uri();',
    '            let jwks = match reqwest::get(&jwks_url).await {',
    '                Ok(resp) => match resp.json::<jsonwebtoken::jwk::JwkSet>().await {',
    '                    Ok(set) => set,',
    '                    Err(_) => return unauthorized("Failed to parse JWKS"),',
    '                },',
    '                Err(_) => return unauthorized("Failed to fetch JWKS"),',
    '            };',
    '',
    '            let jwk = match jwks.find(&kid) {',
    '                Some(k) => k,',
    '                None => return unauthorized("No matching key in JWKS"),',
    '            };',
    '',
    '            let decoding_key = match jsonwebtoken::DecodingKey::from_jwk(jwk) {',
    '                Ok(k) => k,',
    '                Err(_) => return unauthorized("Invalid JWK"),',
    '            };',
    '',
    '            let mut validation = jsonwebtoken::Validation::new(header.alg);',
    '            let issuers = iam_issuers();',
    '            if !issuers.is_empty() {',
    '                validation.set_issuer(&issuers);',
    '            }',
    '            if let Some(aud) = iam_audience() {',
    '                validation.set_audience(&[aud]);',
    '            } else {',
    '                validation.validate_aud = false;',
    '            }',
    '',
    '            match jsonwebtoken::decode::<serde_json::Value>(token, &decoding_key, &validation) {',
    '                Ok(_) => next.run(req).await.into_response(),',
    '                Err(e) => unauthorized(&format!("Token verification failed: {e}")),',
    '            }',
    '        }',
    '        _ => unauthorized("Missing Bearer token"),',
    '    }',
    '}',
    '',
    'fn unauthorized(msg: &str) -> axum::http::Response<axum::body::Body> {',
    '    axum::http::Response::builder()',
    '        .status(401)',
    '        .header("content-type", "application/json")',
    '        .body(axum::body::Body::from(',
    '            serde_json::json!({"error":{"code":"UNAUTHORIZED","message":msg}}).to_string()',
    '        ))',
    '        .unwrap()',
    '}',
    '',
    'pub async fn logging_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let method = req.method().clone();',
    '    let uri = req.uri().clone();',
    '    let start = std::time::Instant::now();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request received",',
    '        "httpRequest": { "method": method.as_str(), "url": uri.to_string() },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    let response = next.run(req).await;',
    '    let duration_ms = start.elapsed().as_millis();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request completed",',
    '        "httpRequest": {',
    '            "method": method.as_str(),',
    '            "url": uri.to_string(),',
    '            "status": response.status().as_u16(),',
    '            "latency": format!("{}ms", duration_ms)',
    '        },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    response',
    '}',
    '',
  ].join('\n');
}

